/* eslint-disable @next/next/no-img-element */
import type { SceneName } from "@/content/types";
import { cn } from "@/lib/cn";

/**
 * FinanceGo's original vector landscapes (Alps, lake, summit, trail, New York,
 * London, campus), used where the brand calls for photography. Each scene is a
 * static SVG in public/scenes, generated by `npm run scenes` from SceneSvg.tsx,
 * so it is downloaded once and cached across pages. Licensed photography can
 * replace a file later without changing any layout.
 */
export function Scene({ name, className, title, priority = false }: { name: SceneName; className?: string; title?: string; priority?: boolean }) {
  return (
    <img
      src={`/scenes/${name}.svg`}
      alt={title ?? ""}
      aria-hidden={title ? undefined : true}
      width={800}
      height={600}
      loading={priority ? "eager" : "lazy"}
      decoding="async"
      draggable={false}
      className={cn("block object-cover", className)}
    />
  );
}
